1	import { useState, useEffect } from "react";
2	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
3	import { Button } from "@/shared/ui/button";
4	import { Input } from "@/shared/ui/input";
5	import { Label } from "@/shared/ui/label";
6	import { Switch } from "@/shared/ui/switch";
7	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
8	import { Separator } from "@/shared/ui/separator";
9	import { Badge } from "@/shared/ui/badge";
10	import { Settings, User, Shield, Database, Bell, Palette } from "lucide-react";
11	import { useAuth } from "@/shared/hooks/useAuth";
12	import { usePermissions } from "@/shared/hooks/usePermissions";
13	import { toast } from "@/shared/hooks/use-toast";
14	import { supabase } from "@/integrations/supabase/client";
15	import { wideError } from "@/shared/lib/telemetry/wide-events";
16	import { useMiaPageContext } from "@/features/mia/hooks/useMiaPageContext";
17	
18	interface ConfiguracaoSistema {
19	  id: string;
20	  chave: string;
21	  valor: string;
22	  descricao: string;
23	  tipo: 'texto' | 'numero' | 'boolean';
24	  categoria: string;
25	}
26	
27	const Configuracoes = () => {
28	  useMiaPageContext({
29	    description: 'Configurações do sistema — perfil do user, permissões, notificações, tema, dados gerais.',
30	    natural_language_hints: '"alterar senha" = aba Conta; "ativar/desativar notificação" = aba Notificações; admin pode mexer em configurações de sistema.',
31	    capabilities: ['atualizar_perfil', 'configurar_notificacoes', 'alterar_tema'],
32	    destructive_actions: ['deletar_conta'],
33	    primary_entity: 'configuracao',
34	  });
35	  const { user, userProfile } = useAuth();
36	  const { isAdmin } = usePermissions();
37	  const [configuracoes, setConfiguracoes] = useState<ConfiguracaoSistema[]>([]);
38	  const [loading, setLoading] = useState(true);
39	  const [saving, setSaving] = useState(false);
40	  const [notificacoesEmail, setNotificacoesEmail] = useState(true);
41	  const [notificacoesPush, setNotificacoesPush] = useState(true);
42	  const [temaEscuro, setTemaEscuro] = useState(false);
43	  const [currentPassword, setCurrentPassword] = useState('');
44	  const [newPassword, setNewPassword] = useState('');
45	  const [confirmNewPassword, setConfirmNewPassword] = useState('');
46	  const [updatingPassword, setUpdatingPassword] = useState(false);
47	
48	  useEffect(() => {
49	    carregarConfiguracoes();
50	    // eslint-disable-next-line react-hooks/exhaustive-deps
51	  }, []);
52	
53	  const carregarConfiguracoes = async () => {
54	    try {
55	      setLoading(true);
56	
57	      // Carregar configurações do sistema (apenas para admins)
58	      if (isAdmin()) {
59	        const { data: configData, error: configError } = await supabase
60	          .from('configuracoes_sistema')
61	          .select('*')
62	          .order('categoria', { ascending: true });
63	
64	        if (configError) throw configError;
65	        setConfiguracoes((configData ?? []) as ConfiguracaoSistema[]);
66	      }
67	
68	      // Carregar preferências do usuário
69	      const { data: prefsData } = await supabase
70	        .from('user_preferences')
71	        .select('*')
72	        .eq('user_id', user?.id ?? '')
73	        .maybeSingle();
74	
75	      if (prefsData) {
76	        setNotificacoesEmail(prefsData.notificacoes_email || true);
77	        setNotificacoesPush(prefsData.notificacoes_push || true);
78	        setTemaEscuro(prefsData.tema_escuro || false);
79	      }
80	    } catch (error) {
81	      wideError('configuracoes.carregar.erro', 'Falha ao carregar configurações', { attributes: { 'operation.name': 'carregarConfiguracoes', 'error.message': error instanceof Error ? error.message : String(error) } });
82	      toast({
83	        title: 'Erro',
84	        description: 'Erro ao carregar configurações',
85	        variant: 'destructive',
86	      });
87	    } finally {
88	      setLoading(false);
89	    }
90	  };
91	
92	  const salvarPreferenciasUsuario = async () => {
93	    try {
94	      setSaving(true);
95	
96	      const { error } = await supabase
97	        .from('user_preferences')
98	        .upsert({
99	          user_id: user?.id ?? '',
100	          notificacoes_email: notificacoesEmail,
101	          notificacoes_push: notificacoesPush,
102	          tema_escuro: temaEscuro,
103	          updated_at: new Date().toISOString()
104	        });
105	
106	      if (error) throw error;
107	
108	      toast({
109	        title: 'Sucesso',
110	        description: 'Preferências salvas com sucesso',
111	      });
112	    } catch (error) {
113	      wideError('configuracoes.preferencias.salvar.erro', 'Falha ao salvar preferências do usuário', { attributes: { 'operation.name': 'salvarPreferenciasUsuario', 'error.message': error instanceof Error ? error.message : String(error) } });
114	      toast({
115	        title: 'Erro',
116	        description: 'Erro ao salvar preferências',
117	        variant: 'destructive',
118	      });
119	    } finally {
120	      setSaving(false);
121	    }
122	  };
123	
124	  const atualizarConfiguracaoSistema = async (
125	    id: string,
126	    novoValor: string,
127	  ) => {
128	    try {
129	      const { error } = await supabase
130	        .from('configuracoes_sistema')
131	        .update({ valor: novoValor })
132	        .eq('id', id);
133	
134	      if (error) throw error;
135	
136	      setConfiguracoes((prev) =>
137	        prev.map((config) =>
138	          config.id === id ? { ...config, valor: novoValor } : config,
139	        ),
140	      );
141	
142	      toast({
143	        title: 'Sucesso',
144	        description: 'Configuração atualizada com sucesso',
145	      });
146	    } catch (error) {
147	      wideError('configuracoes.sistema.atualizar.erro', 'Falha ao atualizar configuração do sistema', { attributes: { 'operation.name': 'atualizarConfiguracaoSistema', 'error.message': error instanceof Error ? error.message : String(error) } });
148	      toast({
149	        title: 'Erro',
150	        description: 'Erro ao atualizar configuração',
151	        variant: 'destructive',
152	      });
153	    }
154	  };
155	
156	  if (loading) {
157	    return (
158	      <div className="container mx-auto p-6">
159	        <div className="flex items-center space-x-2 mb-6">
160	          <Settings className="h-6 w-6" />
161	          <h1 className="text-2xl font-bold">Configurações</h1>
162	        </div>
163	        <div className="text-center py-8">
164	          <p>Carregando configurações...</p>
165	        </div>
166	      </div>
167	    );
168	  }
169	
170	  return (
171	    <div className="container mx-auto p-6">
172	      <div className="flex items-center space-x-2 mb-6">
173	        <Settings className="h-6 w-6" />
174	        <h1 className="text-2xl font-bold">Configurações</h1>
175	      </div>
176	
177	      <Tabs defaultValue="perfil" className="space-y-6">
178	        <TabsList className="grid w-full grid-cols-5">
179	          <TabsTrigger value="perfil" className="flex items-center gap-2">
180	            <User className="h-4 w-4" />
181	            Perfil
182	          </TabsTrigger>
183	          <TabsTrigger value="notificacoes" className="flex items-center gap-2">
184	            <Bell className="h-4 w-4" />
185	            Notificações
186	          </TabsTrigger>
187	          <TabsTrigger value="aparencia" className="flex items-center gap-2">
188	            <Palette className="h-4 w-4" />
189	            Aparência
190	          </TabsTrigger>
191	          <TabsTrigger value="seguranca" className="flex items-center gap-2">
192	            <Shield className="h-4 w-4" />
193	            Segurança
194	          </TabsTrigger>
195	          {isAdmin() && (
196	            <>
197	              <TabsTrigger value="sistema" className="flex items-center gap-2">
198	                <Database className="h-4 w-4" />
199	                Sistema
200	              </TabsTrigger>
201	            </>
202	          )}
203	        </TabsList>
204	
205	        <TabsContent value="perfil">
206	          <Card>
207	            <CardHeader>
208	              <CardTitle>Informações do Perfil</CardTitle>
209	              <CardDescription>
210	                Visualize e gerencie suas informações pessoais
211	              </CardDescription>
212	            </CardHeader>
213	            <CardContent className="space-y-4">
214	              <div className="grid grid-cols-2 gap-4">
215	                <div>
216	                  <Label>Nome</Label>
217	                  <Input value={userProfile?.nome || ''} disabled />
218	                </div>
219	                <div>
220	                  <Label>Username</Label>
221	                  <Input value={userProfile?.username || ''} disabled />
222	                </div>
223	                <div>
224	                  <Label>Email</Label>
225	                  <Input value={user?.email || ''} disabled />
226	                </div>
227	                <div>
228	                  <Label>Loja Padrão</Label>
229	                  <Input value={userProfile?.default_store_id ? `Loja #${userProfile.default_store_id}` : 'Não definida'} disabled />
230	                </div>
231	              </div>
232	
233	              <Separator />
234	
235	              <div className="flex items-center space-x-4">
236	                <div className="flex items-center space-x-2">
237	                  <Badge variant={userProfile?.ativo ? 'default' : 'secondary'}>
238	                    {userProfile?.ativo ? 'Ativo' : 'Inativo'}
239	                  </Badge>
240	                  <Badge
241	                    variant={userProfile?.approved ? 'default' : 'destructive'}
242	                  >
243	                    {userProfile?.approved ? 'Aprovado' : 'Pendente'}
244	                  </Badge>
245	                </div>
246	              </div>
247	            </CardContent>
248	          </Card>
249	        </TabsContent>
250	
251	        <TabsContent value="seguranca">
252	          <Card>
253	            <CardHeader>
254	              <CardTitle>Redefinição de Senha</CardTitle>
255	              <CardDescription>
256	                Altere sua senha com segurança. Confirme a senha atual.
257	              </CardDescription>
258	            </CardHeader>
259	            <CardContent>
260	              <div className="space-y-4">
261	                <div>
262	                  <Label htmlFor="current-password">Senha atual</Label>
263	                  <Input data-mia-field="current-password"
264	                    id="current-password"
265	                    type="password"
266	                    placeholder="••••••••"
267	                    value={currentPassword}
268	                    onChange={(e) => setCurrentPassword(e.target.value)}
269	                  />
270	                </div>
271	                <div>
272	                  <Label htmlFor="new-password">Nova senha</Label>
273	                  <Input data-mia-field="new-password"
274	                    id="new-password"
275	                    type="password"
276	                    placeholder="mín. 8 caracteres"
277	                    value={newPassword}
278	                    onChange={(e) => setNewPassword(e.target.value)}
279	                  />
280	                </div>
281	                <div>
282	                  <Label htmlFor="confirm-password">Confirmar nova senha</Label>
283	                  <Input data-mia-field="confirm-password"
284	                    id="confirm-password"
285	                    type="password"
286	                    placeholder="repita a nova senha"
287	                    value={confirmNewPassword}
288	                    onChange={(e) => setConfirmNewPassword(e.target.value)}
289	                  />
290	                </div>
291	                <div className="pt-2">
292	                  <Button
293	                    onClick={async () => {
294	                      if (!user?.email) {
295	                        toast({
296	                          title: 'Erro',
297	                          description:
298	                            'Usuário não identificado. Faça login novamente.',
299	                          variant: 'destructive',
300	                        });
301	                        return;
302	                      }
303	
304	                      // Validações básicas
305	                      if (newPassword.length < 8) {
306	                        toast({
307	                          title: 'Senha fraca',
308	                          description:
309	                            'A nova senha deve ter pelo menos 8 caracteres.',
310	                        });
311	                        return;
312	                      }
313	                      if (newPassword !== confirmNewPassword) {
314	                        toast({
315	                          title: 'Senhas diferentes',
316	                          description:
317	                            'A confirmação não coincide com a nova senha.',
318	                          variant: 'destructive',
319	                        });
320	                        return;
321	                      }
322	                      if (!currentPassword) {
323	                        toast({
324	                          title: 'Informe a senha atual',
325	                          description:
326	                            'Por favor, informe sua senha atual para confirmar.',
327	                        });
328	                        return;
329	                      }
330	
331	                      try {
332	                        setUpdatingPassword(true);
333	
334	                        // Reautenticar para confirmar a senha atual
335	                        const { error: signInError } =
336	                          await supabase.auth.signInWithPassword({
337	                            email: user.email,
338	                            password: currentPassword,
339	                          });
340	
341	                        if (signInError) {
342	                          toast({
343	                            title: 'Senha atual incorreta',
344	                            description:
345	                              'Verifique sua senha e tente novamente.',
346	                            variant: 'destructive',
347	                          });
348	                          setUpdatingPassword(false);
349	                          return;
350	                        }
351	
352	                        // Atualizar senha
353	                        const { error: updateError } =
354	                          await supabase.auth.updateUser({
355	                            password: newPassword,
356	                          });
357	
358	                        if (updateError) {
359	                          toast({
360	                            title: 'Erro ao atualizar senha',
361	                            description:
362	                              updateError.message ||
363	                              'Tente novamente mais tarde.',
364	                            variant: 'destructive',
365	                          });
366	                          setUpdatingPassword(false);
367	                          return;
368	                        }
369	
370	                        toast({
371	                          title: 'Senha atualizada',
372	                          description: 'Sua senha foi alterada com sucesso.',
373	                        });
374	                        setCurrentPassword('');
375	                        setNewPassword('');
376	                        setConfirmNewPassword('');
377	                      } catch (err) {
378	                        wideError('configuracoes.senha.redefinir.erro', 'Falha ao redefinir senha do usuário', { attributes: { 'operation.name': 'redefinirSenha', 'error.message': err instanceof Error ? err.message : String(err) } });
379	                        toast({
380	                          title: 'Erro inesperado',
381	                          description: 'Não foi possível atualizar sua senha.',
382	                          variant: 'destructive',
383	                        });
384	                      } finally {
385	                        setUpdatingPassword(false);
386	                      }
387	                    }}
388	                    disabled={updatingPassword}
389	                  >
390	                    {updatingPassword ? 'Atualizando...' : 'Atualizar Senha'}
391	                  </Button>
392	                </div>
393	              </div>
394	            </CardContent>
395	          </Card>
396	        </TabsContent>
397	
398	        <TabsContent value="notificacoes">
399	          <Card>
400	            <CardHeader>
401	              <CardTitle>Preferências de Notificação</CardTitle>
402	              <CardDescription>
403	                Configure como você deseja receber notificações
404	              </CardDescription>
405	            </CardHeader>
406	            <CardContent className="space-y-6">
407	              <div className="flex items-center justify-between">
408	                <div className="space-y-0.5">
409	                  <Label>Notificações por Email</Label>
410	                  <p className="text-sm text-muted-foreground">
411	                    Receba atualizações importantes por email
412	                  </p>
413	                </div>
414	                <Switch
415	                  checked={notificacoesEmail}
416	                  onCheckedChange={setNotificacoesEmail}
417	                />
418	              </div>
419	
420	              <Separator />
421	
422	              <div className="flex items-center justify-between">
423	                <div className="space-y-0.5">
424	                  <Label>Notificações Push</Label>
425	                  <p className="text-sm text-muted-foreground">
426	                    Receba notificações em tempo real no navegador
427	                  </p>
428	                </div>
429	                <Switch
430	                  checked={notificacoesPush}
431	                  onCheckedChange={setNotificacoesPush}
432	                />
433	              </div>
434	
435	              <div className="pt-4">
436	                <Button data-mia-action="salvar-preferencias-usuario" onClick={salvarPreferenciasUsuario} disabled={saving}>
437	                  {saving ? 'Salvando...' : 'Salvar Preferências'}
438	                </Button>
439	              </div>
440	            </CardContent>
441	          </Card>
442	        </TabsContent>
443	
444	        <TabsContent value="aparencia">
445	          <Card>
446	            <CardHeader>
447	              <CardTitle>Configurações de Aparência</CardTitle>
448	              <CardDescription>
449	                Personalize a aparência do sistema
450	              </CardDescription>
451	            </CardHeader>
452	            <CardContent className="space-y-6">
453	              <div className="flex items-center justify-between">
454	                <div className="space-y-0.5">
455	                  <Label>Tema Escuro</Label>
456	                  <p className="text-sm text-muted-foreground">
457	                    Ative o modo escuro para reduzir o cansaço visual
458	                  </p>
459	                </div>
460	                <Switch checked={temaEscuro} onCheckedChange={setTemaEscuro} />
461	              </div>
462	
463	              <div className="pt-4">
464	                <Button data-mia-action="salvar-preferencias-usuario" onClick={salvarPreferenciasUsuario} disabled={saving}>
465	                  {saving ? 'Salvando...' : 'Salvar Preferências'}
466	                </Button>
467	              </div>
468	            </CardContent>
469	          </Card>
470	        </TabsContent>
471	
472	        {isAdmin() && (
473	          <TabsContent value="sistema">
474	            <Card>
475	              <CardHeader>
476	                <CardTitle className="flex items-center gap-2">
477	                  <Shield className="h-5 w-5" />
478	                  Configurações do Sistema
479	                </CardTitle>
480	                <CardDescription>
481	                  Configurações avançadas do sistema (apenas administradores)
482	                </CardDescription>
483	              </CardHeader>
484	              <CardContent>
485	                <div className="space-y-6">
486	                  {configuracoes.length === 0 && (
487	                    <p className="text-center text-muted-foreground py-8">
488	                      Nenhuma configuração de sistema encontrada
489	                    </p>
490	                  )}
491	
492	                  {Object.entries(
493	                    configuracoes.reduce(
494	                      (acc, config) => {
495	                        const categoria = config.categoria;
496	                        if (!acc[categoria]) {
497	                          acc[categoria] = [];
498	                        }
499	                        acc[categoria].push(config);
500	                        return acc;
501	                      },
502	                      {} as Record<string, ConfiguracaoSistema[]>,
503	                    ),
504	                  ).map(([categoria, configs]) => (
505	                    <div key={categoria} className="space-y-4">
506	                      <h3 className="text-lg font-semibold capitalize">
507	                        {categoria}
508	                      </h3>
509	                      <div className="space-y-3">
510	                        {configs.map((config) => (
511	                          <div
512	                            key={config.id}
513	                            className="flex items-center justify-between p-3 border rounded-lg"
514	                          >
515	                            <div className="space-y-1">
516	                              <Label>{config.chave}</Label>
517	                              <p className="text-sm text-muted-foreground">
518	                                {config.descricao}
519	                              </p>
520	                            </div>
521	                            <div className="w-48">
522	                              {config.tipo === 'boolean' ? (
523	                                <Switch
524	                                  checked={config.valor === 'true'}
525	                                  onCheckedChange={(checked) =>
526	                                    atualizarConfiguracaoSistema(
527	                                      config.id,
528	                                      checked.toString(),
529	                                    )
530	                                  }
531	                                />
532	                              ) : (
533	                                <Input
534	                                  type={
535	                                    config.tipo === 'numero' ? 'number' : 'text'
536	                                  }
537	                                  value={config.valor}
538	                                  onChange={(e) =>
539	                                    atualizarConfiguracaoSistema(
540	                                      config.id,
541	                                      e.target.value,
542	                                    )
543	                                  }
544	                                />
545	                              )}
546	                            </div>
547	                          </div>
548	                        ))}
549	                      </div>
550	                    </div>
551	                  ))}
552	                </div>
553	              </CardContent>
554	            </Card>
555	          </TabsContent>
556	        )}
557	      </Tabs>
558	    </div>
559	  );
560	};
561	
562	export default Configuracoes;
563
